'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import type { ChartValue } from '@tanstack/charts';
import { motion as createMotionRenderer } from '@tanstack/charts/motion';
import { RendererChart as ChartPrimitive } from '@tanstack/charts/react/tooltip';
import type { RendererChartProps } from '@tanstack/charts/react/tooltip';
import { svgChartRenderer } from '@tanstack/charts/svg/renderer';
import { clsx } from 'clsx';
import type { CSSProperties, ForwardedRef } from 'react';
import { forwardRef } from 'react';
import { normalizeClassName } from '@/lib/moduix/normalizeClassName';
import styles from './Chart.module.css';

const defaultChartRenderer = createMotionRenderer({
  transition: {
    type: 'spring',
    stiffness: 260,
    damping: 30,
    mass: 0.8,
  },
});

const ChartRoot = forwardRef<HTMLElement, HTMLArkProps<'figure'>>(function ChartRoot(
  { className, ...props },
  ref,
) {
  return (
    <ark.figure
      ref={ref as ForwardedRef<HTMLElement>}
      data-scope="chart"
      data-part="root"
      data-slot="chart-root"
      className={clsx(styles.root, normalizeClassName(className))}
      {...props}
    />
  );
});

const ChartPlot = function ChartPlot<
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>({
  className,
  motion = true,
  renderer,
  ...props
}: Omit<RendererChartProps<TDatum, TXValue, TYValue>, 'renderer'> & {
  motion?: boolean;
  renderer?: RendererChartProps<TDatum, TXValue, TYValue>['renderer'];
}) {
  return (
    <ChartPrimitive
      {...props}
      renderer={renderer ?? (motion ? defaultChartRenderer : svgChartRenderer)}
      className={clsx(styles.plot, normalizeClassName(className))}
    />
  );
};

const ChartHeader = forwardRef<HTMLElement, HTMLArkProps<'figcaption'>>(function ChartHeader(
  { className, ...props },
  ref,
) {
  return (
    <ark.figcaption
      ref={ref as ForwardedRef<HTMLElement>}
      data-scope="chart"
      data-part="header"
      data-slot="chart-header"
      className={clsx(styles.header, normalizeClassName(className))}
      {...props}
    />
  );
});

const ChartTitle = forwardRef<HTMLElement, HTMLArkProps<'h3'>>(function ChartTitle(
  { className, ...props },
  ref,
) {
  return (
    <ark.h3
      ref={ref as ForwardedRef<HTMLHeadingElement>}
      data-scope="chart"
      data-part="title"
      data-slot="chart-title"
      className={clsx(styles.title, normalizeClassName(className))}
      {...props}
    />
  );
});

const ChartDescription = forwardRef<HTMLElement, HTMLArkProps<'p'>>(function ChartDescription(
  { className, ...props },
  ref,
) {
  return (
    <ark.p
      ref={ref as ForwardedRef<HTMLParagraphElement>}
      data-scope="chart"
      data-part="description"
      data-slot="chart-description"
      className={clsx(styles.description, normalizeClassName(className))}
      {...props}
    />
  );
});

const ChartLegend = forwardRef<HTMLElement, HTMLArkProps<'ul'>>(function ChartLegend(
  { className, ...props },
  ref,
) {
  return (
    <ark.ul
      ref={ref as ForwardedRef<HTMLUListElement>}
      data-scope="chart"
      data-part="legend"
      data-slot="chart-legend"
      className={clsx(styles.legend, normalizeClassName(className))}
      {...props}
    />
  );
});

const ChartLegendItem = forwardRef<
  HTMLElement,
  HTMLArkProps<'li'> & {
    color?: string;
  }
>(function ChartLegendItem({ className, color, style, ...props }, ref) {
  return (
    <ark.li
      ref={ref as ForwardedRef<HTMLLIElement>}
      data-scope="chart"
      data-part="legend-item"
      data-slot="chart-legend-item"
      className={clsx(styles.legendItem, normalizeClassName(className))}
      style={
        color
          ? ({ '--moduix-chart-legend-indicator-color': color, ...style } as CSSProperties)
          : style
      }
      {...props}
    />
  );
});

const Chart = Object.assign(ChartRoot, {
  Root: ChartRoot,
  Plot: ChartPlot,
  Header: ChartHeader,
  Title: ChartTitle,
  Description: ChartDescription,
  Legend: ChartLegend,
  LegendItem: ChartLegendItem,
});

export { Chart };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: grid;
    width: 100%;
    min-width: 0;
    gap: var(--moduix-chart-gap, var(--moduix-spacing-5));
    margin: 0;
    padding: var(--moduix-chart-padding, var(--moduix-spacing-5));
    border: var(--moduix-chart-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-chart-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-chart-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-chart-bg, var(--moduix-color-card));
    box-shadow: var(--moduix-chart-shadow, var(--moduix-shadow-sm));
    color: var(--moduix-color-card-foreground);
  }

  .plot {
    min-width: 0;
    border-radius: var(--moduix-chart-plot-radius, var(--moduix-radius-md));
    color: var(--moduix-chart-axis-color, var(--moduix-color-muted-foreground));

    --ts-chart-tooltip-background: var(--moduix-chart-tooltip-bg, var(--moduix-color-popover));
    --ts-chart-tooltip-border: var(
        --moduix-chart-tooltip-border-width,
        var(--moduix-border-width-sm)
      )
      solid var(--moduix-chart-tooltip-border-color, var(--moduix-color-border));
    --ts-chart-tooltip-border-radius: var(--moduix-chart-tooltip-radius, var(--moduix-radius-md));
    --ts-chart-tooltip-color: var(
      --moduix-chart-tooltip-color,
      var(--moduix-color-popover-foreground)
    );
    --ts-chart-tooltip-font: var(--moduix-weight-medium)
      var(--moduix-chart-tooltip-font-size, var(--moduix-text-xs)) /
      var(--moduix-chart-tooltip-line-height, var(--moduix-line-height-text-xs))
      var(--moduix-font-sans);
    --ts-chart-tooltip-padding: var(--moduix-chart-tooltip-padding, var(--moduix-spacing-3));
    --ts-chart-tooltip-shadow: var(--moduix-chart-tooltip-shadow, var(--moduix-shadow-lg));

    & :global(.ts-chart) {
      border-radius: var(--moduix-chart-plot-radius, var(--moduix-radius-md));
      outline: none;
    }

    & :global(.ts-chart:focus-visible) {
      outline: var(
          --moduix-chart-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-chart-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-chart-focus-ring-offset, var(--moduix-focus-ring-offset));
    }
  }

  .header {
    display: grid;
    gap: var(--moduix-spacing-1);
  }

  .title {
    margin: 0;
    color: currentColor;
    font-size: var(--moduix-text-lg);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-lg);
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .legend {
    display: flex;
    flex-wrap: wrap;
    gap: var(--moduix-spacing-3);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .legendItem {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);

    &::before {
      width: var(--moduix-spacing-2-5);
      height: var(--moduix-spacing-2-5);
      flex: none;
      border-radius: var(--moduix-radius-full);
      background-color: var(
        --moduix-chart-legend-indicator-color,
        var(--moduix-color-muted-foreground)
      );
      box-shadow: inset 0 0 0 var(--moduix-border-width-sm) rgb(0 0 0 / 8%);
      content: '';
    }
  }
}
